import ghidra.app.script.GhidraScript;import java.nio.file.*;public class EngineRefs extends GhidraScript {public void run() throws Exception {StringBuilder b=new StringBuilder();for(var ref:getReferencesTo(toAddr(getScriptArgs()[1]))){var f=getFunctionContaining(ref.getFromAddress());b.append(ref.getFromAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\n");}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}